@Composable
fun ListLinkScreen(
    links: List<Link>,
    onNavigate: (String) -> Unit,
    modifier: Modifier = Modifier
) {
    var showAddLinkDialog by remember { mutableStateOf(false) }
    var selectedLink by remember { mutableStateOf<Link?>(null) }
    val customColors = LocalCustomColors.current

    Column(
        modifier = modifier
            .fillMaxSize()
            .background(customColors.background)
            .padding(16.dp)
    ) {
        LazyColumn(
            verticalArrangement = Arrangement.spacedBy(12.dp),
            contentPadding = PaddingValues(vertical = 8.dp)
        ) {
            items(links) { link ->
                LinkItem(
                    link = link,
                    onEditClick = {
                        selectedLink = link
                        showAddLinkDialog = true
                    },
                    onOpenClick = {
                        onNavigate(link.url)
                    }
                )
            }
        }
    }

    // Add/Edit Link Dialog
    if (showAddLinkDialog) {
        AddLinkDialog(
            link = selectedLink,
            onDismiss = {
                showAddLinkDialog = false
                selectedLink = null
            },
            onSave = { editedLink ->
                // Handle save logic here
                showAddLinkDialog = false
                selectedLink = null
            }
        )
    }
}

@Composable
private fun LinkItem(
    link: Link,
    onEditClick: () -> Unit,
    onOpenClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val customColors = LocalCustomColors.current
    val customTypography = LocalCustomTypography.current

    // Format date
    val dateFormat = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
    val formattedDate = dateFormat.format(Date(link.dateTimeCreated))

    Card(
        modifier = modifier.fillMaxWidth(),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = customColors.surface
        ),
        elevation = CardDefaults.cardElevation(
            defaultElevation = 2.dp
        )
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp)
        ) {
            // 1. Header Section
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.weight(1f)
                ) {
                    // Icon
                    Icon(
                        painter = painterResource(R.drawable.link_add), // Replace with your link icon
                        contentDescription = "Link",
                        tint = customColors.primary,
                        modifier = Modifier.size(24.dp)
                    )

                    Spacer(modifier = Modifier.width(12.dp))

                    // Title
                    Text(
                        text = link.title,
                        style = customTypography.h6,
                        color = customColors.text,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f)
                    )
                }

                // Edit Icon
                Icon(
                    painter = painterResource(R.drawable.arrow_right), // Replace with your edit icon
                    contentDescription = "Edit",
                    tint = customColors.subtext,
                    modifier = Modifier
                        .size(20.dp)
                        .clickable { onEditClick() }
                        .padding(2.dp)
                )
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Divider
            HorizontalDivider(
                thickness = 1.dp,
                color = customColors.border
            )

            Spacer(modifier = Modifier.height(12.dp))

            // 2. Notes Section (Description)
            Text(
                text = link.description,
                style = customTypography.body,
                color = customColors.subtext,
                maxLines = 3,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(16.dp))

            // 3. Bottom Section
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Date Created
                Text(
                    text = formattedDate,
                    style = customTypography.caption,
                    color = customColors.subtext
                )

                // Open Button
                Button(
                    onClick = onOpenClick,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = customColors.primary
                    ),
                    shape = RoundedCornerShape(8.dp),
                    modifier = Modifier.height(36.dp)
                ) {
                    Text(
                        text = "Open",
                        style = customTypography.button,
                        color = customColors.surface
                    )
                }
            }
        }
    }
}

@Composable
fun AddLinkDialog(
    link: Link? = null,
    onDismiss: () -> Unit,
    onSave: (Link) -> Unit
) {
    val customColors = LocalCustomColors.current
    val customTypography = LocalCustomTypography.current

    var title by remember { mutableStateOf(link?.title ?: "") }
    var url by remember { mutableStateOf(link?.url ?: "") }
    var description by remember { mutableStateOf(link?.description ?: "") }

    val isEditing = link != null
    val dialogTitle = if (isEditing) "Edit Link" else "Add Link"
    val confirmButtonText = if (isEditing) "Update" else "Add"

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(
                text = dialogTitle,
                style = customTypography.h6,
                color = customColors.text
            )
        },
        text = {
            Column(
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                OutlinedTextField(
                    value = title,
                    onValueChange = { title = it },
                    label = {
                        Text(
                            "Title",
                            color = customColors.subtext
                        )
                    },
                    textStyle = customTypography.body.copy(color = customColors.text),
                    modifier = Modifier.fillMaxWidth()
                )

                OutlinedTextField(
                    value = url,
                    onValueChange = { url = it },
                    label = {
                        Text(
                            "URL",
                            color = customColors.subtext
                        )
                    },
                    textStyle = customTypography.body.copy(color = customColors.text),
                    modifier = Modifier.fillMaxWidth()
                )

                OutlinedTextField(
                    value = description,
                    onValueChange = { description = it },
                    label = {
                        Text(
                            "Description",
                            color = customColors.subtext
                        )
                    },
                    textStyle = customTypography.body.copy(color = customColors.text),
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 3
                )
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    val updatedLink = link?.copy(
                        title = title,
                        url = url,
                        description = description
                    ) ?: Link(
                        id = java.util.UUID.randomUUID().toString(),
                        tagId = "", // You'll need to provide the appropriate tagId
                        url = url,
                        iconUrl = null,
                        title = title,
                        description = description,
                        dateTimeCreated = System.currentTimeMillis()
                    )
                    onSave(updatedLink)
                },
                enabled = title.isNotBlank() && url.isNotBlank()
            ) {
                Text(
                    text = confirmButtonText,
                    style = customTypography.button,
                    color = if (title.isNotBlank() && url.isNotBlank()) 
                        customColors.primary else customColors.textDisabled
                )
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(
                    text = "Cancel",
                    style = customTypography.button,
                    color = customColors.subtext
                )
            }
        }
    )
}

