@Composable
fun AddLinkDialog(
    link: Link? = null,
    onDismiss: () -> Unit,
    onSave: (Link) -> Unit
) {
    val customColors = LocalCustomColors.current
    val customTypography = LocalCustomTypography.current

    var title by remember { mutableStateOf(link?.title ?: "") }
    var url by remember { mutableStateOf(link?.url ?: "") }
    var description by remember { mutableStateOf(link?.description ?: "") }

    val isEditing = link != null
    val dialogTitle = if (isEditing) "Edit Link" else "Add Link"
    val confirmButtonText = if (isEditing) "Update" else "Add"

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(
                text = dialogTitle,
                style = customTypography.h6,
                color = customColors.text
            )
        },
        text = {
            Column(
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                OutlinedTextField(
                    value = title,
                    onValueChange = { title = it },
                    label = {
                        Text(
                            "Title",
                            color = customColors.subtext
                        )
                    },
                    textStyle = customTypography.body.copy(color = customColors.text),
                    modifier = Modifier.fillMaxWidth()
                )

                OutlinedTextField(
                    value = url,
                    onValueChange = { url = it },
                    label = {
                        Text(
                            "URL",
                            color = customColors.subtext
                        )
                    },
                    textStyle = customTypography.body.copy(color = customColors.text),
                    modifier = Modifier.fillMaxWidth()
                )

                OutlinedTextField(
                    value = description,
                    onValueChange = { description = it },
                    label = {
                        Text(
                            "Description",
                            color = customColors.subtext
                        )
                    },
                    textStyle = customTypography.body.copy(color = customColors.text),
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 3
                )
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    val updatedLink = link?.copy(
                        title = title,
                        url = url,
                        description = description
                    ) ?: Link(
                        id = java.util.UUID.randomUUID().toString(),
                        tagId = "", // You'll need to provide the appropriate tagId
                        url = url,
                        iconUrl = null,
                        title = title,
                        description = description,
                        dateTimeCreated = System.currentTimeMillis()
                    )
                    onSave(updatedLink)
                },
                enabled = title.isNotBlank() && url.isNotBlank()
            ) {
                Text(
                    text = confirmButtonText,
                    style = customTypography.button,
                    color = if (title.isNotBlank() && url.isNotBlank()) 
                        customColors.primary else customColors.textDisabled
                )
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(
                    text = "Cancel",
                    style = customTypography.button,
                    color = customColors.subtext
                )
            }
        }
    )
}

